// NewCheckingStream wraps stream and makes sure event UIDs and timing are in place
func NewCheckingStream(stream Stream, clock clockwork.Clock) Stream {
	return &CheckingStream{
		stream:       stream,
		clock:        clock,
		uidGenerator: utils.NewRealUID(),
	}
}

